// flow-core.ts: written by AKit (docs/design/flows.md F1, F19). Pure: no Pi, no files.
// Route lookup, visits and the next state. Same answers as Swift's FlowRouting.next; both run
// the golden vectors in fixtures/flow-vectors.

/** The `akit-flow-format` this runner reads. A newer flow file means "run Apply in AKit" (F20). */
export const FLOW_FORMAT = 1;
/** The lowest Pi the runner supports, and the highest one the tests passed on (F20). */
export const MIN_PI = "1.0.4";
export const TESTED_PI = "1.0.4";
/** The reserved route target that ends the run. */
export const END = "end";
export const DEFAULT_MAX_LOOPS = 3;

export type Outcome = "done" | "failed" | "blocked";
/** Why a run ended. `no-handoff`, `check-refused` and `commit-failed` come from the runner, never from `nextStep`. */
export type Stop = "done" | "visit-cap" | "no-route" | "unknown-step" | "no-handoff" | "check-refused" | "commit-failed";

export interface FlowStep {
	id: string;
	/** Left out: Pi. "claude-code": the step runs as `claude -p`, read only (F21). */
	harness?: string;
	agent: string;
	model: string;
	thinking?: string;
	/** What the step does, in the model's words (the Feature template's come from PurpleFlow). */
	prompt?: string;
	skills?: string[];
	tools?: string[];
	paths?: string[];
	bash?: boolean;
	extensions?: string[];
	gate?: boolean;
	checks?: string[];
	maxLoops?: number;
	routes?: Record<string, string>;
}

export interface Flow {
	"akit-flow-format": number;
	name: string;
	minPi?: string;
	tools?: string[];
	steps: FlowStep[];
}

export type Visits = Record<string, number>;

export interface RunState {
	/** The step that just ended. */
	step: string;
	/** How often each step has started. */
	visits: Visits;
}

export type Decision =
	| { next: string; visits: Visits }
	| { stop: Stop; step?: string; visits: Visits };

export function isOutcome(value: unknown): value is Outcome {
	return value === "done" || value === "failed" || value === "blocked";
}

/** `outcome:reason`, then `outcome:*`; a `done` without a route goes to the next step (the end after
 * the last); `failed` and `blocked` need a route; a target over its `maxLoops` stops. */
export function nextStep(flow: Flow, state: RunState, outcome: Outcome, reason = ""): Decision {
	const index = flow.steps.findIndex((s) => s.id === state.step);
	if (index < 0) return { stop: "unknown-step", step: state.step, visits: state.visits };
	const routes = flow.steps[index].routes ?? {};
	let target: string;
	const exact = reason ? routes[`${outcome}:${reason}`] : undefined;
	if (exact !== undefined) target = exact;
	else if (routes[`${outcome}:*`] !== undefined) target = routes[`${outcome}:*`];
	else if (outcome === "done") target = index + 1 < flow.steps.length ? flow.steps[index + 1].id : END;
	else return { stop: "no-route", step: state.step, visits: state.visits };
	if (target === END) return { stop: "done", visits: state.visits };
	const next = flow.steps.find((s) => s.id === target);
	if (!next) return { stop: "unknown-step", step: target, visits: state.visits };
	const count = (state.visits[target] ?? 0) + 1;
	if (count > (next.maxLoops ?? DEFAULT_MAX_LOOPS)) return { stop: "visit-cap", step: target, visits: state.visits };
	return { next: target, visits: { ...state.visits, [target]: count } };
}

/** The first step of a run, with its first visit. */
export function firstStep(flow: Flow): Decision {
	const first = flow.steps[0];
	if (!first) return { stop: "done", visits: {} };
	return { next: first.id, visits: { [first.id]: 1 } };
}

/** Compares dotted versions ("1.0.4" < "1.10.0"); a pre-release tail is ignored. */
export function compareVersions(a: string, b: string): number {
	const parts = (v: string) => v.replace(/^v/, "").split(/[-+ ]/)[0].split(".").map((n) => Number.parseInt(n, 10) || 0);
	const x = parts(a);
	const y = parts(b);
	for (let i = 0; i < Math.max(x.length, y.length); i++) {
		const d = (x[i] ?? 0) - (y[i] ?? 0);
		if (d !== 0) return d < 0 ? -1 : 1;
	}
	return 0;
}

/** Why a flow file can't run with this runner, or undefined. */
export function formatProblem(flow: Flow): string | undefined {
	const format = flow["akit-flow-format"];
	if (typeof format !== "number") return `The flow ${flow.name ?? "?"} has no akit-flow-format; run Apply in AKit.`;
	if (format > FLOW_FORMAT)
		return `The flow ${flow.name} has akit-flow-format ${format}, newer than this runner (${FLOW_FORMAT}); run Apply in AKit.`;
	if (!Array.isArray(flow.steps) || flow.steps.length === 0) return `The flow ${flow.name} has no steps.`;
	return undefined;
}

/** The lowest Pi a flow needs: the flow's own minPi or the runner's, whichever is higher. */
export function requiredPi(flow: Flow): string {
	return flow.minPi && compareVersions(flow.minPi, MIN_PI) > 0 ? flow.minPi : MIN_PI;
}

/** A run id `YYYYMMDD-HHMM-xxxx` (local time, 4 hex). */
export function runId(now: Date, hex: string): string {
	const p = (n: number) => String(n).padStart(2, "0");
	return `${now.getFullYear()}${p(now.getMonth() + 1)}${p(now.getDate())}-${p(now.getHours())}${p(now.getMinutes())}-${hex.slice(0, 4)}`;
}

/** The fallback when a step ended without `flow_handoff` (a deviation): the outcome from a last
 * line `outcome: failed[:reason]` of the child's answer, or undefined without one. */
export function parseOutcome(text: string): { outcome: Outcome; reason: string } | undefined {
	for (const line of text.split("\n").reverse()) {
		const m = /^\s*outcome:\s*(done|failed|blocked)(?::\s*([\w.-]+))?\s*$/i.exec(line);
		if (m) return { outcome: m[1].toLowerCase() as Outcome, reason: m[2] ?? "" };
	}
	return undefined;
}

/** OMC's verify-command rules, as AKit's check (FlowCheck.isSafeCommand): at most 10 commands,
 * each a plain command of at most 120 characters. The runner checks them again (F19). */
export const MAX_CHECK_COMMANDS = 10;
export const MAX_CHECK_LENGTH = 120;

export function isSafeCommand(command: string): boolean {
	return command.length <= MAX_CHECK_LENGTH && /^[A-Za-z][A-Za-z0-9 _.:/=%@-]*$/.test(command);
}

/** Hides env-like secrets in text shown or logged (A21): `NAME=value` where the name says token,
 * key, secret, password or auth; `Authorization:` / `Bearer` values; long token-like strings
 * (GitHub, GitLab, Slack, AWS key ids); `user:pass@` in URLs; `--password X` / `-p X`. */
export function redact(text: string): string {
	return text
		.replace(/\b([a-z][a-z0-9+.-]*:\/\/)[^\s/:@]+:[^\s/@]+@/gi, "$1***@")
		.replace(/(^|\s)(--password|-p)(\s+|=)("[^"]*"|'[^']*'|\S+)/g, "$1$2$3***")
		.replace(/\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g, "***")
		.replace(/\bgithub_pat_[A-Za-z0-9_]{20,}\b/g, "***")
		.replace(/\b(Bearer|Basic)\s+[A-Za-z0-9._~+/=-]+/g, "$1 ***")
		.replace(/\b([A-Za-z0-9_]*(?:TOKEN|KEY|SECRET|PASSWORD|PASSWD|AUTH|CREDENTIALS?)[A-Za-z0-9_]*)\s*([=:])\s*("[^"]*"|'[^']*'|\S+)/gi, "$1$2***")
		.replace(/\b(?:sk|pk|ghp|gho|ghs|ghu|glpat|xox[abps])[-_][A-Za-z0-9_-]{12,}\b/g, "***");
}

"""####
    static let flow_git_ts = ####"""
// flow-git.ts: written by AKit (docs/design/flows.md F8, F9). The run's git: its worktree outside
// the project tree on the branch `akit-flow/<run>`, one commit per finished step with trailers,
// and reading those trailers back on resume.

import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

export const BRANCH_PREFIX = "akit-flow/";

/** The run's worktree, outside the project tree. Review's path rule: AKit Review keeps a run's
 * worktree at `~/.akit/local/review/runs/<run>/worktree` on the branch `akit-review/<run>`
 * (ReviewPaths.run in AKitCore/Sources/AKitReview/ReviewCatalog.swift, Gather.swift); a flow run's
 * is `~/.akit/local/flows/runs/<run>/worktree` on `akit-flow/<run>`. */
export function worktreeFolder(run: string): string {
	return join(homedir(), ".akit", "local", "flows", "runs", run, "worktree");
}

export function git(cwd: string, args: string[]): { ok: boolean; out: string; err: string } {
	const r = spawnSync("git", args, { cwd, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
	return { ok: r.status === 0, out: (r.stdout ?? "").trimEnd(), err: (r.stderr ?? r.error?.message ?? "").trim() };
}

export interface Worktree {
	path: string;
	branch: string;
	/** The project commit the run branch starts from. */
	base: string;
}

/** Adds the run's worktree on a new branch at the project's HEAD. */
export function createWorktree(project: string, run: string): Worktree | { error: string } {
	const head = git(project, ["rev-parse", "--verify", "HEAD"]);
	if (!head.ok) return { error: "The project has no commit yet; a flow runs on a branch from HEAD." };
	const path = worktreeFolder(run);
	const branch = BRANCH_PREFIX + run;
	mkdirSync(dirname(path), { recursive: true });
	const added = git(project, ["worktree", "add", "-q", "-b", branch, path, head.out]);
	if (!added.ok) return { error: `git worktree add failed: ${added.err}` };
	return { path, branch, base: head.out };
}

/** `git status --porcelain` lines of the worktree: uncommitted and untracked changes. */
export function changes(worktree: string): string[] {
	const r = git(worktree, ["status", "--porcelain", "--untracked-files=all"]);
	return r.out ? r.out.split("\n") : [];
}

/** Commits everything in the worktree (empty commits too: the trailers mark the finished step). */
export function commit(worktree: string, message: string, trailers: Record<string, string>): { commit: string } | { error: string } {
	const added = git(worktree, ["add", "-A"]);
	if (!added.ok) return { error: added.err };
	const subject = message.split("\n")[0].trim() || "Flow step";
	const lines = Object.entries(trailers).map(([k, v]) => `${k}: ${v}`).join("\n");
	const done = git(worktree, ["commit", "-q", "--allow-empty", "-m", subject, "-m", lines]);
	if (!done.ok) return { error: done.err || "git commit failed" };
	return { commit: git(worktree, ["rev-parse", "HEAD"]).out };
}

export interface FlowCommit {
	commit: string;
	trailers: Record<string, string>;
}

/** The run's commits after `base`, newest first, with their `Flow-*` trailers. */
export function flowCommits(worktree: string, run: string, base: string): FlowCommit[] {
	const r = git(worktree, ["log", "--format=%H%x1f%B%x1e", `${base}..HEAD`]);
	if (!r.ok || !r.out) return [];
	const commits: FlowCommit[] = [];
	for (const entry of r.out.split("\x1e")) {
		const [hash, body] = entry.trim().split("\x1f");
		if (!hash || body === undefined) continue;
		const trailers: Record<string, string> = {};
		for (const m of body.matchAll(/^(Flow-[A-Za-z]+):\s*(.+)$/gm)) trailers[m[1]] = m[2].trim();
		if (trailers["Flow-Run"] === run) commits.push({ commit: hash, trailers });
	}
	return commits;
}

/** Puts the worktree back to `commit`, dropping uncommitted and untracked changes. */
export function resetTo(worktree: string, commit: string): boolean {
	return git(worktree, ["reset", "-q", "--hard", commit]).ok && git(worktree, ["clean", "-q", "-fd"]).ok;
}

/** What the run branch changed against its base, the work tree included. */
export function diffFromBase(worktree: string, base: string): string {
	const stat = git(worktree, ["diff", "--stat", base]).out;
	const diff = git(worktree, ["diff", base]).out;
	return stat || diff ? `${stat}\n\n${diff}\n` : "No changes against the base.\n";
}

export function worktreeExists(path: string): boolean {
	return existsSync(join(path, ".git"));
}

"""####
    static let flow_record_ts = ####"""
// flow-record.ts: written by AKit (docs/design/flows.md F4, F9). The run record in
// <main checkout>/.pi/akit-flow/runs/<run-id>/: events.jsonl (the truth, append-only), run.json
// (a cache, written atomically), handoffs/, evidence/, sessions/, lock. AKit's FlowRun reader reads it.

import { spawn } from "node:child_process";
import { appendFileSync, closeSync, existsSync, mkdirSync, openSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync, writeSync } from "node:fs";
import { join } from "node:path";
import type { Outcome, Visits } from "./flow-core.ts";
import type { Tokens } from "./pi-adapter.ts";

export const RUN_SCHEMA = "akit-flow-run/1";
export const EVENT_SCHEMA = "akit-flow-event/1";
export const HANDOFF_SCHEMA = "akit-flow-handoff/1";
export const EVIDENCE_SCHEMA = "akit-flow-evidence/1";
/** Lines of a check's output kept in its evidence file. */
export const EVIDENCE_LINES = 40;

export function runsFolder(mainCheckout: string): string {
	return join(mainCheckout, ".pi", "akit-flow", "runs");
}

/** Token fields in the record's names; an unknown field stays out (null), never zero. */
export function recordTokens(t: Tokens): Record<string, number | null> {
	return { input: t.input ?? null, output: t.output ?? null, cache_read: t.cacheRead ?? null, cost: t.cost ?? null };
}

export function writeAtomic(path: string, value: unknown): void {
	const tmp = `${path}.tmp-${process.pid}`;
	writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`);
	renameSync(tmp, path);
}

export function appendEvent(folder: string, type: string, fields: Record<string, unknown>): void {
	const line = { schema: EVENT_SCHEMA, type, time: new Date().toISOString(), ...fields };
	appendFileSync(join(folder, "events.jsonl"), `${JSON.stringify(line)}\n`);
}

export interface RecordedEvent {
	type?: string;
	step?: string;
	attempt?: number;
	outcome?: Outcome;
	reason?: string;
	flow?: string;
	task?: string;
	[key: string]: unknown;
}

/** events.jsonl read tolerantly: lines that are not JSON objects are skipped. */
export function readEvents(folder: string): RecordedEvent[] {
	const path = join(folder, "events.jsonl");
	if (!existsSync(path)) return [];
	const events: RecordedEvent[] = [];
	for (const line of readFileSync(path, "utf8").split("\n")) {
		if (!line.trim()) continue;
		try {
			const value = JSON.parse(line) as unknown;
			if (value && typeof value === "object" && !Array.isArray(value)) events.push(value as RecordedEvent);
		} catch {
			// A torn last line after a crash; the events before it hold.
		}
	}
	return events;
}

/** Visits per step, counted from step-start events (as AKit's reader does). */
export function visitsFrom(events: RecordedEvent[]): Visits {
	const visits: Visits = {};
	for (const e of events) if (e.type === "step-start" && e.step) visits[e.step] = (visits[e.step] ?? 0) + 1;
	return visits;
}

function alive(pid: number): boolean {
	try {
		process.kill(pid, 0);
		return true;
	} catch (error) {
		return (error as NodeJS.ErrnoException).code === "EPERM";
	}
}

/** Takes the run's lock atomically (create-exclusive); refuses (returns the holder's pid) when
 * another live process holds it. A stale lock (dead holder, or no pid) is removed and taken again. */
export function takeLock(folder: string): number | undefined {
	const path = join(folder, "lock");
	for (let round = 0; round < 3; round++) {
		try {
			const fd = openSync(path, "wx");
			try {
				writeSync(fd, `${process.pid}\n`);
			} finally {
				closeSync(fd);
			}
			return undefined;
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
		}
		let pid = Number.NaN;
		try {
			pid = Number.parseInt(readFileSync(path, "utf8").trim(), 10);
		} catch {
			// Removed between our open and read: try again.
			continue;
		}
		if (pid === process.pid) return undefined;
		if (Number.isFinite(pid) && alive(pid)) return pid;
		rmSync(path, { force: true });
	}
	const pid = Number.parseInt(readFileSync(path, "utf8").trim(), 10);
	return Number.isFinite(pid) ? pid : -1;
}

export function releaseLock(folder: string): void {
	const path = join(folder, "lock");
	if (existsSync(path) && readFileSync(path, "utf8").trim() === String(process.pid)) rmSync(path);
}

export function createRunFolder(mainCheckout: string, id: string): string {
	const folder = join(runsFolder(mainCheckout), id);
	mkdirSync(join(folder, "sessions"), { recursive: true });
	mkdirSync(join(folder, "handoffs"), { recursive: true });
	mkdirSync(join(folder, "evidence"), { recursive: true });
	return folder;
}

/** Run ids start with date and time, so the newest sorts last. */
export function latestRun(mainCheckout: string): string | undefined {
	const root = runsFolder(mainCheckout);
	if (!existsSync(root)) return undefined;
	const names = readdirSync(root).filter((n) => !n.startsWith(".")).sort();
	return names.length ? join(root, names[names.length - 1]) : undefined;
}

export function handoffName(index: number, step: string, attempt: number, session: string | undefined): string {
	return `${String(index + 1).padStart(2, "0")}-${step}-a${attempt}-${session ?? "no-session"}.json`;
}

/** `NN-<step>`: the step's number in the flow and its id. */
export function stepKey(index: number, step: string): string {
	return `${String(index + 1).padStart(2, "0")}-${step}`;
}

export interface CheckResult {
	command: string;
	exit: number | null;
	/** The last EVIDENCE_LINES lines of stdout and stderr together. */
	tail: string[];
}

/** One check command, run by the runner (never the model), split on spaces and started without a
 * shell: AKit's rule allows no shell syntax anyway. */
function runCheck(command: string, cwd: string, signal?: AbortSignal): Promise<CheckResult> {
	return new Promise((resolve) => {
		const [file, ...args] = command.split(/\s+/).filter(Boolean);
		let output = "";
		const keep = (data: Buffer) => {
			output = (output + data.toString()).slice(-64_000);
		};
		const proc = spawn(file, args, { cwd, shell: false, stdio: ["ignore", "pipe", "pipe"], signal, timeout: 30 * 60_000 });
		proc.stdout.on("data", keep);
		proc.stderr.on("data", keep);
		proc.on("error", (error) => {
			output += `${error.message}\n`;
		});
		proc.on("close", (code) => {
			const lines = output.replace(/\n$/, "").split("\n");
			resolve({ command, exit: code, tail: output ? lines.slice(-EVIDENCE_LINES) : [] });
		});
	});
}

/** Runs a step's checks in `cwd` and writes `evidence/NN-<step>-aN-checks.json`, one file per attempt (F19). */
export async function runChecks(folder: string, key: string, run: string, step: { id: string; attempt: number }, commands: string[],
	cwd: string, signal?: AbortSignal): Promise<string> {
	const checks: CheckResult[] = [];
	for (const command of commands) checks.push(await runCheck(command, cwd, signal));
	const path = join(folder, "evidence", `${key}-a${step.attempt}-checks.json`);
	writeAtomic(path, { schema: EVIDENCE_SCHEMA, run, step, time: new Date().toISOString(), checks });
	return path;
}

/** A step's checks are green only with an evidence file whose every command exited 0. */
export function checksGreen(path: string): boolean {
	try {
		const value = JSON.parse(readFileSync(path, "utf8")) as { schema?: string; checks?: CheckResult[] };
		return value.schema === EVIDENCE_SCHEMA && Array.isArray(value.checks) && value.checks.length > 0 && value.checks.every((c) => c.exit === 0);
	} catch {
		return false;
	}
}

"""####
    static let flow_view_ts = ####"""
// flow-view.ts: written by AKit (docs/design/flows.md F18). Pure: no Pi, no files. What the Pi row
// and the step overlay show for this Pi process's run, built from the child's JSON events.

import { type Flow, redact } from "./flow-core.ts";

export type StepState = "pending" | "running" | "done" | "failed";

export type Entry =
	| { kind: "tool"; id: string; name: string; args: string; status: "running" | "ok" | "error" }
	| { kind: "text"; text: string };

export interface StepView {
	id: string;
	model: string;
	state: StepState;
	/** Input + output tokens Pi reported; undefined until a message gave them. */
	tokens?: number;
	/** The latest attempt's tool calls and assistant text, as Pi shows them: never tool output. */
	entries: Entry[];
}

export interface RunView {
	flow: string;
	run: string;
	steps: StepView[];
	deviations: number;
}

export function newView(flow: Flow, run: string): RunView {
	return { flow: flow.name, run, steps: flow.steps.map((s) => ({ id: s.id, model: s.model, state: "pending", entries: [] })), deviations: 0 };
}

/** A tool call's short arguments, as Pi's own line shows them; redacted (A21). */
export function shortArgs(name: string, args: unknown): string {
	const a = (args && typeof args === "object" ? args : {}) as Record<string, unknown>;
	let text: string;
	if (name === "bash" && typeof a.command === "string") text = a.command;
	else if (typeof a.path === "string") text = a.path;
	else if (typeof a.pattern === "string") text = a.pattern;
	else text = Object.keys(a).sort().join(", ");
	text = redact(text).replace(/\s+/g, " ").trim();
	return text.length > 80 ? `${text.slice(0, 79)}…` : text;
}

/** Adds one child event to its step; returns true when the view changed. */
export function viewEvent(step: StepView, event: Record<string, unknown>): boolean {
	if (event.type === "tool_execution_start" && typeof event.toolName === "string") {
		step.entries.push({ kind: "tool", id: String(event.toolCallId ?? ""), name: event.toolName, args: shortArgs(event.toolName, event.args), status: "running" });
		return true;
	}
	if (event.type === "tool_execution_end") {
		const entry = [...step.entries].reverse().find((e) => e.kind === "tool" && e.id === String(event.toolCallId ?? "") && e.status === "running");
		if (entry && entry.kind === "tool") entry.status = event.isError ? "error" : "ok";
		return Boolean(entry);
	}
	if (event.type !== "message_end") return false;
	const message = event.message as Record<string, unknown> | undefined;
	if (message?.role !== "assistant") return false;
	const usage = (message.usage ?? {}) as Record<string, unknown>;
	if (typeof usage.input === "number" || typeof usage.output === "number")
		step.tokens = (step.tokens ?? 0) + (Number(usage.input) || 0) + (Number(usage.output) || 0);
	const content = Array.isArray(message.content) ? message.content : [];
	const text = content.filter((p) => p?.type === "text" && typeof p.text === "string").map((p) => p.text as string).join("\n").trim();
	if (text) step.entries.push({ kind: "text", text: redact(text) });
	return true;
}

function count(tokens: number): string {
	return tokens >= 1_000_000 ? `${(tokens / 1_000_000).toFixed(1)}M` : tokens >= 1000 ? `${Math.round(tokens / 1000)}k` : String(tokens);
}

const MARK: Record<StepState, string> = { pending: "○", running: "●", done: "✓", failed: "✗" };

/** `1 plan ✓ m 12k  2 code ● 3k  3 checks ○   ⚠ 1   alt+1…3 view`: model's last name part, tokens. */
export function rowLine(view: RunView, keys: string[]): string {
	const parts = view.steps.map((s, i) => [`${i + 1} ${s.id} ${MARK[s.state]}`, s.state === "pending" ? "" : s.model.split("/").pop() ?? "",
		s.tokens !== undefined ? count(s.tokens) : ""].filter(Boolean).join(" "));
	let line = parts.join("  ");
	if (view.deviations > 0) line += `   ⚠ ${view.deviations}`;
	line += keys.length > 0 ? `   ${keys[0]}${keys.length > 1 ? `…${keys[keys.length - 1].split("+").pop()}` : ""} view` : "   /flow show <n>";
	return line;
}

/** The overlay's lines for step n (1-based). */
export function overlayLines(view: RunView, n: number): string[] {
	const step = view.steps[n - 1];
	if (!step) return [`Flow ${view.flow} has no step ${n}.`];
	const lines = [`Flow ${view.flow} · step ${n} ${step.id} ${MARK[step.state]} · ${step.model}${step.tokens !== undefined ? ` · ${count(step.tokens)} tokens` : ""}`, ""];
	if (step.entries.length === 0) lines.push(step.state === "pending" ? "Not started." : "No events in this Pi yet.");
	for (const e of step.entries) {
		if (e.kind === "tool") lines.push(`${e.status === "running" ? "…" : e.status === "ok" ? "✓" : "✗"} ${e.name} ${e.args}`.trimEnd());
		else lines.push(...e.text.split("\n"));
	}
	lines.push("", "Esc closes");
	return lines;
}

/** Pi 1.0.4's default keys (core/keybindings.js and pi-tui's keybindings.js, the installed copy):
 * the step shortcuts must not take one of them. */
export const BUILTIN_KEYS = new Set([
	"alt+b", "alt+backspace", "alt+d", "alt+delete", "alt+down", "alt+enter", "alt+f", "alt+left", "alt+p", "alt+q", "alt+right", "alt+up",
	"alt+v", "alt+y", "alt+z", "backspace", "ctrl+-", "ctrl+a", "ctrl+b", "ctrl+backspace", "ctrl+c", "ctrl+d", "ctrl+down", "ctrl+e", "ctrl+f",
	"ctrl+g", "ctrl+k", "ctrl+l", "ctrl+left", "ctrl+n", "ctrl+o", "ctrl+p", "ctrl+q", "ctrl+r", "ctrl+right", "ctrl+s", "ctrl+shift+down",
	"ctrl+shift+f", "ctrl+shift+up", "ctrl+t", "ctrl+u", "ctrl+up", "ctrl+v", "ctrl+w", "ctrl+x", "ctrl+y", "ctrl+z", "delete", "down", "end",
	"enter", "escape", "home", "left", "right", "shift+ctrl+o", "shift+ctrl+p", "shift+enter", "shift+l", "shift+t", "shift+tab", "tab", "up",
	"ctrl+shift+n", "ctrl+shift+t", "alt+shift+t", "ctrl+alt+]", "ctrl+]", "ctrl+shift+g", "ctrl+home", "ctrl+end",
]);

/** `alt+1` … `alt+9`, without the keys Pi or the user's keybindings.json already use (a clash
 * means no shortcut for that step; `/flow show` still works). */
export function pickShortcuts(steps: number, taken: Iterable<string>): string[] {
	const used = new Set([...BUILTIN_KEYS, ...[...taken].map((k) => k.toLowerCase())]);
	const keys: string[] = [];
	for (let n = 1; n <= Math.min(steps, 9); n++) if (!used.has(`alt+${n}`)) keys.push(`alt+${n}`);
	return keys;
}

"""####
    static let pi_adapter_ts = ####"""
// pi-adapter.ts: written by AKit (docs/design/flows.md F20). The only file that talks to Pi: the
// `pi` command (version, features, child runs) and the extension API. A Pi change touches only this.
//
// The child spawn and the JSON event parsing are adapted from Pi's example extension
// examples/extensions/subagent/index.ts (@earendil-works/pi-coding-agent 1.5.2, MIT licence,
// Copyright (c) Mario Zechner and contributors). Changes: own flags (no -p, no --no-session),
// stdin /dev/null, own process group killed as a group, unknown fields kept as unknown.

import { execFile, spawn } from "node:child_process";
import { appendFileSync, existsSync, readdirSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { readFile } from "node:fs/promises";
import type { ExtensionAPI, ExtensionCommandContext, ExtensionContext } from "@earendil-works/pi-coding-agent";

export type { ExtensionAPI, ExtensionCommandContext, ExtensionContext };

/** The Pi command; tests put a fake `pi` first on PATH. */
export const PI = process.env.AKIT_FLOW_PI ?? "pi";

/** Flags the runner needs; without one the run refuses (F20). */
export const REQUIRED_FLAGS = ["--mode", "--session-dir", "--no-skills", "--skill", "--no-extensions", "--extension", "--model"] as const;
/** Flags with a fallback: `--thinking` → `--model M:<level>`, `--tools` → left out (the guard enforces). */
export const OPTIONAL_FLAGS = ["--thinking", "--tools"] as const;

export interface PiInfo {
	version: string | undefined;
	/** Flag → found in `pi --help`. */
	features: Record<string, boolean>;
	/** Extension API features found at load. */
	api: Record<string, boolean>;
}

function run(command: string, args: string[]): Promise<{ code: number | null; stdout: string; stderr: string }> {
	return new Promise((resolve) => {
		execFile(command, args, { timeout: 20_000, maxBuffer: 4 * 1024 * 1024 }, (error, stdout, stderr) => {
			const code = error ? (typeof (error as { code?: unknown }).code === "number" ? (error as { code: number }).code : null) : 0;
			resolve({ code, stdout: String(stdout), stderr: String(stderr) });
		});
	});
}

/** `pi --version` and the flags in `pi --help`; features are checked, not guessed from the version. */
export async function detectPi(ctx?: ExtensionContext): Promise<PiInfo> {
	const version = await run(PI, ["--version"]);
	const help = await run(PI, ["--help"]);
	const match = /(\d+\.\d+\.\d+[\w.-]*)/.exec(version.stdout + version.stderr);
	const text = help.stdout + help.stderr;
	const features: Record<string, boolean> = {};
	for (const flag of [...REQUIRED_FLAGS, ...OPTIONAL_FLAGS]) {
		features[flag] = new RegExp(`(^|[\\s,])${flag.replace(/-/g, "\\-")}(?=[\\s,=<]|$)`, "m").test(text);
	}
	const ui = ctx?.ui as unknown as Record<string, unknown> | undefined;
	const api: Record<string, boolean> = {
		setWidget: typeof ui?.setWidget === "function",
		setStatus: typeof ui?.setStatus === "function",
		confirm: typeof ui?.confirm === "function",
		editor: typeof ui?.editor === "function",
		custom: typeof ui?.custom === "function",
	};
	return { version: version.code === 0 && match ? match[1] : undefined, features, api };
}

/** The required flags this Pi lacks. */
export function missingFlags(info: PiInfo): string[] {
	return REQUIRED_FLAGS.filter((flag) => !info.features[flag]);
}

/** Reads a flow file. Pi ships the `yaml` package; without it the file must be JSON (JSON is YAML). */
export async function readFlowFile(path: string): Promise<unknown> {
	const text = await readFile(path, "utf8");
	try {
		const name = "yaml";
		const yaml = (await import(name)) as { parse: (text: string) => unknown };
		return yaml.parse(text);
	} catch {
		return JSON.parse(text);
	}
}

export interface ChildOptions {
	cwd: string;
	sessionDir: string;
	model: string;
	thinking?: string;
	skills: string[];
	tools: string[];
	/** `-e` paths: the guard, akit-record, the step's own list (F15). */
	extensions: string[];
	prompt: string;
	info: PiInfo;
	/** Added to the child's environment (AKIT_FLOW_HANDOFF). */
	env?: Record<string, string>;
	signal?: AbortSignal;
	/** Each parsed JSON event of the child, for the row and the overlay (F18). */
	onEvent?: (event: Record<string, unknown>) => void;
}

/** The child command (flows.md, "Child command form"); no `-p`, the task is the prompt argument. */
export function childArgs(o: ChildOptions): string[] {
	const args = ["--mode", "json", "--session-dir", o.sessionDir, "-ns"];
	for (const skill of o.skills) args.push("--skill", skill);
	args.push("-ne");
	for (const ext of o.extensions) args.push("-e", ext);
	if (o.thinking && o.info.features["--thinking"]) args.push("--model", o.model, "--thinking", o.thinking);
	else args.push("--model", o.thinking ? `${o.model}:${o.thinking}` : o.model);
	// `-t` is a hint (the guard enforces); it would also hide the runner's own flow_handoff.
	if (o.tools.length > 0 && o.info.features["--tools"]) args.push("-t", [...o.tools, "flow_handoff"].join(","));
	args.push("--", o.prompt);
	return args;
}

/** A token field Pi did not give is undefined (unknown), never zero (F20). */
export interface Tokens {
	input?: number;
	output?: number;
	cacheRead?: number;
	cost?: number;
}

export interface ChildResult {
	code: number | null;
	signal: string | null;
	aborted: boolean;
	spawnError?: string;
	/** The session id from the child's session header, when Pi gave one. */
	session?: string;
	/** The last assistant text. */
	text: string;
	tokens: Tokens;
	/** Claude Code's structured output: the handoff part of a claude-code step (F21). */
	structured?: unknown;
	/** Event types this runner does not know, counted. */
	unknownEvents: number;
	badLines: number;
	stderr: string;
	pid?: number;
}

function add(total: number | undefined, value: unknown): number | undefined {
	return typeof value === "number" && total !== undefined ? total + value : undefined;
}

/** Tolerant reader of Pi's JSON events: known types are parsed, the rest counted. */
export function readEvent(line: string, result: ChildResult, seen: { assistant: boolean }, onEvent?: (event: Record<string, unknown>) => void): void {
	if (!line.trim()) return;
	let event: Record<string, unknown>;
	try {
		const parsed = JSON.parse(line) as unknown;
		if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("not an object");
		event = parsed as Record<string, unknown>;
	} catch {
		result.badLines++;
		return;
	}
	try {
		onEvent?.(event);
	} catch {
		// The view never stops a run.
	}
	if (event.type === "session") {
		if (typeof event.id === "string") result.session = event.id;
		return;
	}
	if (event.type !== "message_end") {
		if (typeof event.type !== "string" || !KNOWN_EVENTS.has(event.type)) result.unknownEvents++;
		return;
	}
	const message = event.message as Record<string, unknown> | undefined;
	if (!message || message.role !== "assistant") return;
	const usage = (message.usage ?? {}) as Record<string, unknown>;
	const cost = usage.cost as Record<string, unknown> | number | undefined;
	if (!seen.assistant) {
		seen.assistant = true;
		result.tokens = { input: 0, output: 0, cacheRead: 0, cost: 0 };
	}
	result.tokens.input = add(result.tokens.input, usage.input);
	result.tokens.output = add(result.tokens.output, usage.output);
	result.tokens.cacheRead = add(result.tokens.cacheRead, usage.cacheRead);
	result.tokens.cost = add(result.tokens.cost, typeof cost === "number" ? cost : cost?.total);
	const content = message.content;
	if (Array.isArray(content)) {
		const text = content
			.filter((part): part is { type: string; text: string } => part?.type === "text" && typeof part.text === "string")
			.map((part) => part.text)
			.join("\n");
		if (text) result.text = text;
	} else if (typeof content === "string") {
		result.text = content;
	}
}

const KNOWN_EVENTS = new Set([
	"agent_start", "agent_end", "turn_start", "turn_end", "message_start", "message_update",
	"tool_execution_start", "tool_execution_update", "tool_execution_end", "auto_compaction_start",
	"auto_compaction_end", "auto_retry_start", "auto_retry_end",
]);

/** Starts one child in its own process group; stdin is /dev/null; abort kills the whole group.
 * Pi by default; a Claude Code step passes its own command, arguments and line reader (F21). */
export function runChild(o: ChildOptions, command = PI, args = childArgs(o),
	reader?: (line: string, result: ChildResult) => void): Promise<ChildResult> {
	const result: ChildResult = { code: null, signal: null, aborted: false, text: "", tokens: {}, unknownEvents: 0, badLines: 0, stderr: "" };
	const seen = { assistant: false };
	const read = reader ?? ((line: string, r: ChildResult) => readEvent(line, r, seen, o.onEvent));
	return new Promise((resolve) => {
		let buffer = "";
		let settled = false;
		let killTimer: ReturnType<typeof setTimeout> | undefined;
		const finish = () => {
			if (settled) return;
			settled = true;
			if (killTimer) clearTimeout(killTimer);
			o.signal?.removeEventListener("abort", abort);
			resolve(result);
		};
		const proc = spawn(command, args, {
			cwd: o.cwd, shell: false, detached: true, stdio: ["ignore", "pipe", "pipe"], env: { ...process.env, ...o.env },
		});
		result.pid = proc.pid;
		const killGroup = (sig: NodeJS.Signals) => {
			if (proc.pid === undefined) return;
			try {
				process.kill(-proc.pid, sig);
			} catch {
				// The group is gone already.
			}
		};
		function abort() {
			if (proc.exitCode !== null || proc.signalCode !== null) return;
			result.aborted = true;
			killGroup("SIGTERM");
			killTimer = setTimeout(() => killGroup("SIGKILL"), 5000);
		}
		proc.stdout.on("data", (data: Buffer) => {
			buffer += data.toString();
			const lines = buffer.split("\n");
			buffer = lines.pop() ?? "";
			for (const line of lines) read(line, result);
		});
		proc.stderr.on("data", (data: Buffer) => {
			result.stderr = (result.stderr + data.toString()).slice(-8000);
		});
		proc.on("close", (code, signal) => {
			if (buffer.trim()) read(buffer, result);
			result.code = code;
			result.signal = signal;
			finish();
		});
		proc.on("error", (error) => {
			result.spawnError = error.message;
			finish();
		});
		if (o.signal) {
			if (o.signal.aborted) abort();
			else o.signal.addEventListener("abort", abort, { once: true });
		}
	});
}

/** The child's session file in its --session-dir: Pi names it `<time>_<session id>.jsonl`. */
export function sessionFile(sessionDir: string, session: string | undefined): string | undefined {
	if (!session || !existsSync(sessionDir)) return undefined;
	return readdirSync(sessionDir).find((name) => name.endsWith(".jsonl") && name.includes(session));
}

/** Extension API calls the runner makes. */
export function registerFlowCommand(pi: ExtensionAPI, handler: (args: string, ctx: ExtensionCommandContext) => Promise<void>): void {
	pi.registerCommand("flow", {
		description: "Run an AKit flow: /flow [name] <task>, /flow resume",
		handler,
	});
}

/** The tool `akit_flow`: the model may start a flow when the user asks in words (F11). */
export function registerStartTool(pi: ExtensionAPI, handler: (params: { flow?: string; task: string }, ctx: ExtensionContext) => Promise<string>): void {
	pi.registerTool({
		name: "akit_flow",
		label: "AKit flow",
		description: "Start an AKit flow (a fixed chain of agent steps) when the user asks for one in words, e.g. \"do it by the Feature flow\". The user is asked to confirm first.",
		parameters: {
			type: "object",
			properties: {
				flow: { type: "string", description: "The flow's name; leave out for the project's default flow." },
				task: { type: "string", description: "The task for the flow, as the user said it." },
			},
			required: ["task"],
			additionalProperties: false,
		},
		async execute(_id, params, _signal, _update, ctx) {
			return { content: [{ type: "text", text: await handler(params as { flow?: string; task: string }, ctx) }], details: undefined };
		},
	});
}

export function onShutdown(pi: ExtensionAPI, handler: () => void): void {
	pi.on("session_shutdown", () => handler());
}

export function say(ctx: ExtensionContext, message: string, level: "info" | "warning" | "error" = "info"): void {
	if (typeof ctx.ui?.notify === "function") ctx.ui.notify(message, level);
}

export function status(ctx: ExtensionContext, text: string | undefined): void {
	if (typeof ctx.ui?.setStatus === "function") ctx.ui.setStatus("akit-flow", text);
}

/** Test log of the UI calls (make test-flows-e2e): one JSON line per call when AKIT_FLOW_UI_LOG is set. */
function uiLog(entry: Record<string, unknown>): void {
	const path = process.env.AKIT_FLOW_UI_LOG;
	if (!path) return;
	try {
		appendFileSync(path, `${JSON.stringify({ time: new Date().toISOString(), ...entry })}\n`);
	} catch {
		// Only a test log.
	}
}

/** The step row below the editor (1.0.4 has the placement; an older Pi draws it above). */
export function showRow(ctx: ExtensionContext, line: string | undefined): void {
	if (typeof ctx.ui?.setWidget !== "function") return;
	ctx.ui.setWidget("akit-flow", line === undefined ? undefined : [line], { placement: "belowEditor" });
	uiLog({ call: "setWidget", lines: line === undefined ? [] : [line], placement: "belowEditor" });
}

/** Keys the user bound in Pi's keybindings.json: a step shortcut must not take them. */
export function userKeys(): string[] {
	const dir = process.env.PI_CODING_AGENT_DIR ?? join(homedir(), ".pi", "agent");
	try {
		const value = JSON.parse(readFileSync(join(dir, "keybindings.json"), "utf8")) as Record<string, unknown>;
		return Object.values(value).flatMap((v) => (Array.isArray(v) ? v : [v])).filter((k): k is string => typeof k === "string");
	} catch {
		return [];
	}
}

/** One shortcut per key; `alt+N` opens step N. */
export function registerStepShortcuts(pi: ExtensionAPI, keys: string[], open: (n: number, ctx: ExtensionContext) => Promise<void>): void {
	for (const key of keys) {
		const n = Number(key.split("+").pop());
		pi.registerShortcut(key, { description: `AKit flow: show step ${n}`, handler: (ctx) => open(n, ctx) });
	}
	uiLog({ call: "shortcuts", keys });
}

type Width = { truncateToWidth?: (text: string, width: number) => string; visibleWidth?: (text: string) => number };
let tuiHelpers: Width | undefined;

/** pi-tui's width helpers inside Pi; outside it (tests) a plain cut by characters. */
async function helpers(): Promise<Width> {
	if (tuiHelpers) return tuiHelpers;
	try {
		const name = "@earendil-works/pi-tui";
		tuiHelpers = (await import(name)) as Width;
	} catch {
		tuiHelpers = {};
	}
	return tuiHelpers;
}

/** The step overlay (ctx.ui.custom): `lines()` is read on each render, `subscribe` asks for a
 * render on new events; Esc closes. No copy button: the text is only drawn. */
export async function showOverlay(ctx: ExtensionContext, step: number, lines: () => string[], subscribe: (render: () => void) => () => void): Promise<void> {
	if (typeof ctx.ui?.custom !== "function") {
		say(ctx, lines().join("\n"));
		return;
	}
	const width = await helpers();
	const cut = (text: string, w: number) => (width.truncateToWidth ? width.truncateToWidth(text, w) : [...text].slice(0, w).join(""));
	uiLog({ call: "overlay", state: "open", step, lines: lines() });
	await ctx.ui.custom<void>((tui, _theme, _keys, done) => {
		const stop = subscribe(() => tui.requestRender());
		return {
			render: (w: number) => lines().flatMap((l) => l.split("\n")).map((l) => cut(l, Math.max(1, w))),
			handleInput: (data: string) => {
				if (data === "\x1b" || data === "\x1b[27u") {
					stop();
					done();
				}
			},
			invalidate: () => {},
			dispose: stop,
		};
	}, { overlay: true });
	uiLog({ call: "overlay", state: "closed", step });
}

